//! Official IETF RFC 8391 §7 companion KATs for XMSS-SHA2_10_256.
//! Hex generated by xmss-reference (tarball sha256 in kat/SOURCE.txt).
//! This is the proof. Not a product seal. Does not write ANS.

use crate::adrs::Adrs;
use crate::params::{N, NBytes};
use crate::wots::{self, WotsPk, WotsSig};
use crate::xmss::{self, XmssPk, XmssSig, SIG_BYTES};

fn unhex(s: &str) -> Vec<u8> {
    hex::decode(s.trim()).expect("official KAT hex")
}

fn n32(s: &str) -> NBytes {
    let v = unhex(s);
    assert_eq!(v.len(), N);
    let mut a = [0u8; N];
    a.copy_from_slice(&v);
    a
}

fn flatten_wots(x: &[[u8; N]; 67]) -> Vec<u8> {
    let mut v = Vec::with_capacity(67 * N);
    for b in x {
        v.extend_from_slice(b);
    }
    v
}

/// Official test/vectors.c WOTS+ address BEFORE expand/sign mutation:
/// addr[i] = 500000000 * i
fn wots_kat_addr() -> Adrs {
    let mut w = [0u32; 8];
    for i in 0..8 {
        w[i] = 500_000_000u32.wrapping_mul(i as u32);
    }
    Adrs::from_words(w)
}

pub fn wots_kat() -> Result<(), String> {
    let sk_seed = n32("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    let pub_seed = n32("00020406080a0c0e10121416181a1c1e20222426282a2c2e30323436383a3c3e");
    let msg = n32("000306090c0f1215181b1e2124272a2d303336393c3f4245484b4e5154575a5d");
    let expect_pk = unhex(include_str!("../kat/wots_pk.hex"));
    let expect_sig = unhex(include_str!("../kat/wots_sig.hex"));
    assert_eq!(expect_pk.len(), 67 * N);
    assert_eq!(expect_sig.len(), 67 * N);

    let mut adrs = wots_kat_addr();
    let sk = wots::expand_sk_adrs(&sk_seed, &pub_seed, &mut adrs);
    let mut adrs = wots_kat_addr();
    let pk: WotsPk = wots::pk_from_sk_adrs(&sk, &pub_seed, &mut adrs);
    let mut adrs = wots_kat_addr();
    let sig: WotsSig = wots::sign_adrs(&sk, &msg, &pub_seed, &mut adrs);

    let pk_b = flatten_wots(&pk);
    let sig_b = flatten_wots(&sig);
    if pk_b != expect_pk {
        return Err(format!(
            "WOTS_PK mismatch first_diff={}",
            first_diff(&pk_b, &expect_pk)
        ));
    }
    if sig_b != expect_sig {
        return Err(format!(
            "WOTS_SIG mismatch first_diff={}",
            first_diff(&sig_b, &expect_sig)
        ));
    }
    Ok(())
}

fn first_diff(a: &[u8], b: &[u8]) -> String {
    let n = a.len().min(b.len());
    for i in 0..n {
        if a[i] != b[i] {
            return format!("byte {i} got {:02x} want {:02x}", a[i], b[i]);
        }
    }
    format!("len got {} want {}", a.len(), b.len())
}

fn official_seed() -> (NBytes, NBytes, NBytes) {
    let mut seed = [0u8; 3 * N];
    for (i, b) in seed.iter_mut().enumerate() {
        *b = i as u8;
    }
    let mut sk_seed = [0u8; N];
    let mut sk_prf = [0u8; N];
    let mut pub_seed = [0u8; N];
    sk_seed.copy_from_slice(&seed[..N]);
    sk_prf.copy_from_slice(&seed[N..2 * N]);
    pub_seed.copy_from_slice(&seed[2 * N..]);
    (sk_seed, sk_prf, pub_seed)
}

pub fn xmss_kat() -> Result<(XmssPk, XmssSig, XmssSig), String> {
    let (sk_seed, sk_prf, pub_seed) = official_seed();
    let (mut sk, pk) = xmss::keygen_from_seed(sk_seed, sk_prf, pub_seed);
    let expect_pk = unhex(include_str!("../kat/xmss_pk.hex"));
    let got_pk = pk.to_bytes();
    if got_pk.as_slice() != expect_pk.as_slice() {
        return Err(format!(
            "XMSS_PK mismatch first_diff={}",
            first_diff(&got_pk, &expect_pk)
        ));
    }

    let msg = [0x25u8];
    let sig0 = xmss::sign(&mut sk, &msg).map_err(|e| e.to_string())?;
    let got0 = sig0.to_bytes();
    let expect0 = unhex(include_str!("../kat/xmss_sig_idx0.hex"));
    if got0 != expect0 {
        return Err(format!(
            "XMSS_SIG_IDX0 mismatch first_diff={}",
            first_diff(&got0, &expect0)
        ));
    }
    if !xmss::verify(&pk, &msg, &sig0) {
        return Err("verify idx0 failed on official message".into());
    }

    let (mut sk512, pk512) = xmss::keygen_from_seed(sk_seed, sk_prf, pub_seed);
    if pk512.to_bytes() != pk.to_bytes() {
        return Err("keygen_from_seed not deterministic".into());
    }
    sk512.idx = 512;
    let sig512 = xmss::sign(&mut sk512, &msg).map_err(|e| e.to_string())?;
    if sig512.idx != 512 {
        return Err(format!("idx512 got {}", sig512.idx));
    }
    let got512 = sig512.to_bytes();
    if got512.len() != SIG_BYTES {
        return Err(format!("sig512 len {}", got512.len()));
    }
    let expect512 = unhex(include_str!("../kat/xmss_sig_idx512.hex"));
    if got512 != expect512 {
        return Err(format!(
            "XMSS_SIG_IDX512 mismatch first_diff={}",
            first_diff(&got512, &expect512)
        ));
    }
    if !xmss::verify(&pk, &msg, &sig512) {
        return Err("verify idx512 failed on official message".into());
    }
    Ok((pk, sig0, sig512))
}

/// Parser proof: official hex → from_bytes → verify. Same path the auditor uses.
pub fn official_sig_parses_and_verifies() -> Result<(), String> {
    let pk = XmssPk::from_bytes(&unhex(include_str!("../kat/xmss_pk.hex")))
        .map_err(|e| e.to_string())?;
    let sig0 = XmssSig::from_bytes(&unhex(include_str!("../kat/xmss_sig_idx0.hex")))
        .map_err(|e| e.to_string())?;
    let sig512 = XmssSig::from_bytes(&unhex(include_str!("../kat/xmss_sig_idx512.hex")))
        .map_err(|e| e.to_string())?;
    if sig0.idx != 0 {
        return Err(format!("parsed idx0 {}", sig0.idx));
    }
    if sig512.idx != 512 {
        return Err(format!("parsed idx512 {}", sig512.idx));
    }
    let msg = [0x25u8];
    if !xmss::verify(&pk, &msg, &sig0) {
        return Err("parsed official idx0 does not verify".into());
    }
    if !xmss::verify(&pk, &msg, &sig512) {
        return Err("parsed official idx512 does not verify".into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ietf_wots_plus_sha2_256() {
        wots_kat().unwrap();
    }

    #[test]
    fn ietf_xmss_sha2_10_256() {
        xmss_kat().unwrap();
    }

    #[test]
    fn official_hex_from_bytes_verifies() {
        official_sig_parses_and_verifies().unwrap();
    }
}
